                        new_sum_red1 = prev_sum_red + A[i][j]
                        new_total1 = prev_total + (A[i][j] + B[i][j])
                        current_dp[new_sum_red1].add(new_total1)
                        new_sum_red2 = prev_sum_red + B[i][j]
                        new_total2 = prev_total + (A[i][j] + B[i][j])
